<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_customizer_footer( $wp_customize ) { $wp_customize->add_section( 'sd_footer', array( 'title' => __( 'Footer', 'social-discovery' ), 'panel' => 'sd_settings' ) ); $wp_customize->add_setting( 'sd_footer_layout', array( 'default' => 'default', 'sanitize_callback' => 'sd_sanitize_select' ) ); $wp_customize->add_control( 'sd_footer_layout', array( 'label' => 'Footer layout', 'section' => 'sd_footer', 'type' => 'select', 'choices' => array( 'default' => 'Default', 'centered' => 'Centered', 'minimal' => 'Minimal' ) ) ); foreach ( array( 'sd_footer_background' => 'Background', 'sd_footer_text_color' => 'Text color', 'sd_footer_heading_color' => 'Heading color' ) as $id => $label ) { $wp_customize->add_setting( $id, array( 'default' => sd_get_option( $id ), 'sanitize_callback' => 'sanitize_hex_color' ) ); $wp_customize->add_control( new WP_Customize_Color_Control( $wp_customize, $id, array( 'label' => $label, 'section' => 'sd_footer' ) ) ); } foreach ( array( 'sd_footer_description' => 'Description', 'sd_copyright' => 'Copyright text' ) as $id => $label ) { $wp_customize->add_setting( $id, array( 'default' => sd_get_option( $id ), 'sanitize_callback' => 'sanitize_textarea_field' ) ); $wp_customize->add_control( $id, array( 'label' => $label, 'section' => 'sd_footer', 'type' => 'textarea' ) ); } foreach ( array( 'sd_footer_logo' => 'Show footer logo', 'sd_footer_social' => 'Show social links', 'sd_footer_border' => 'Show footer border' ) as $id => $label ) { $wp_customize->add_setting( $id, array( 'default' => sd_get_option( $id ), 'sanitize_callback' => 'wp_validate_boolean' ) ); $wp_customize->add_control( $id, array( 'label' => $label, 'section' => 'sd_footer', 'type' => 'checkbox' ) ); } foreach ( array( 'facebook' => 'Facebook', 'instagram' => 'Instagram', 'youtube' => 'YouTube', 'tiktok' => 'TikTok', 'linkedin' => 'LinkedIn', 'x' => 'X', 'github' => 'GitHub', 'whatsapp' => 'WhatsApp' ) as $key => $label ) { $id = 'sd_social_' . $key; $wp_customize->add_setting( $id, array( 'default' => '', 'sanitize_callback' => 'sd_sanitize_url' ) ); $wp_customize->add_control( $id, array( 'label' => $label . ' URL', 'section' => 'sd_footer', 'type' => 'url' ) ); } }
add_action( 'customize_register', 'sd_customizer_footer' );
